import { useId, useMemo, useState } from 'react';
import {
  Alert,
  Button,
  Input,
  Select,
  Stack,
  Switch,
  FormField,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLES: { value: Role; label: string }[] = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const emailId = useId();
  const roleId = useId();

  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = useMemo(() => EMAIL_RE.test(email.trim()), [email]);
  const error = touched && !isValid ? 'Введите адрес вида name@example.com' : undefined;

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
    setRole('viewer');
    setNotify(true);
  }

  return (
    <Stack gap="var(--jx-space-4)">
      {invitedEmail && (
        <Alert
          variant="success"
          title="Приглашение отправлено"
          closable
          onClose={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ к команде.
        </Alert>
      )}

      <form onSubmit={handleSubmit} noValidate>
        <Stack gap="var(--jx-space-4)">
          <FormField
            htmlFor={emailId}
            label="Электронная почта"
            hint="Участник получит ссылку для входа в команду."
            error={error}
          >
            <Input
              id={emailId}
              type="email"
              name="email"
              value={email}
              placeholder="name@example.com"
              invalid={Boolean(error)}
              onChange={(event) => setEmail(event.target.value)}
              onBlur={() => setTouched(true)}
            />
          </FormField>

          <FormField htmlFor={roleId} label="Роль">
            <Select
              id={roleId}
              name="role"
              value={role}
              onChange={(event) => setRole(event.target.value as Role)}
            >
              {ROLES.map((item) => (
                <option key={item.value} value={item.value}>
                  {item.label}
                </option>
              ))}
            </Select>
          </FormField>

          <Switch
            name="notify"
            checked={notify}
            onChange={(event) => setNotify(event.target.checked)}
            label="Отправить уведомление на почту"
          />

          <Button type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </Button>
        </Stack>
      </form>
    </Stack>
  );
}

